import React, { useState } from "react";
import DefineHomework from "./components/DefineHomework";
import GradeSubmission from "./components/GradeSubmission";
import Analysis from "./components/Analysis";

export default function App() {
  const [homework, setHomework] = useState(null);
  const [subs, setSubs] = useState([]);

  return (
    <div className="max-w-3xl mx-auto p-6 space-y-8">
      <h1 className="text-3xl font-bold text-center">🏫 Homework Grader</h1>

      <div className="card bg-white shadow-lg rounded-2xl p-6">
        <h2 className="text-xl font-semibold mb-4">1. Define Homework</h2>
        <DefineHomework onSave={setHomework} />
      </div>

      {homework && (
        <div className="card bg-white shadow-lg rounded-2xl p-6">
          <h2 className="text-xl font-semibold mb-4">2. Grade Submission</h2>
          <GradeSubmission
            homework={homework}
            onSubmit={r => setSubs(prev=>[...prev,r])}
          />
        </div>
      )}

      {subs.length > 0 && (
        <div className="card bg-white shadow-lg rounded-2xl p-6">
          <h2 className="text-xl font-semibold mb-4">3. Analysis</h2>
          <Analysis submissions={subs} />
        </div>
      )}
    </div>
  );
}
